use system.collections.list

fn double_all(xs List<int>) List<int>
    var out = List<int>()
    for x in xs
        out.push(x * 2)
    out

fn main()
    let nums = List([1, 2, 3, 4])
    let doubled = double_all(nums)
    var total = 0
    for d in doubled
        total = total + d
    println(f"doubled={doubled.length()} total={total}")

